import type { ShoppingItem as ItemRow } from "@life/db";
import { addDays, addShoppingItem, buildShoppingList, deleteShoppingItem, SHOPPING_CATEGORIES as CATEGORIES } from "@life/db/pulso";
import { SHOPPING_CATEGORY_LABELS, type ShoppingCategory, type ShoppingItem, type ShoppingList } from "@/contract";
import { today } from "./daily";
import { maybe, ms, nn, ok, P, rows } from "./db";
import type { Ctx, OpTable } from "./types";

// The shopping list on Supabase, generated by @life/db/pulso from the active
// plan's dated meals (the same code the web runs). «Ya tengo» is the phone's
// `pantry` column.

type Row = ItemRow & { pantry?: boolean };

const category = (c: string): ShoppingCategory => ((CATEGORIES as readonly string[]).includes(c) ? (c as ShoppingCategory) : "otros");

const toItem = (row: Row): ShoppingItem => ({
  id: row.id,
  name: row.name,
  amount: row.amount,
  quantity: nn(row.quantity),
  unit: row.unit,
  category: category(row.category),
  source: row.source,
  checked: row.checked,
  pantry: row.pantry ?? false,
  note: row.note,
  updatedAt: ms(row.updated_at),
});

async function view(ctx: Ctx): Promise<ShoppingList> {
  const [list, items, plan] = await Promise.all([
    P(ctx).from("shopping_lists").select("*").maybeSingle(),
    P(ctx).from("shopping_items").select("*"),
    P(ctx).from("diet_plans").select("id").eq("active", true).maybeSingle(),
  ]);
  const meta = maybe(list);
  const active = maybe(plan);
  const order = (c: ShoppingCategory) => CATEGORIES.indexOf(c);
  const all = (rows(items) as Row[]).map(toItem).sort((a, b) => order(a.category) - order(b.category) || a.name.localeCompare(b.name, "es"));
  const toBuy = all.filter((i) => !i.pantry);
  const pending = toBuy.filter((i) => !i.checked);
  const text = CATEGORIES.map((c) => {
    const lines = pending.filter((i) => i.category === c).map((i) => `- ${i.name}${i.amount ? ` (${i.amount})` : ""}`);
    return lines.length ? `${SHOPPING_CATEGORY_LABELS[c]}\n${lines.join("\n")}` : null;
  })
    .filter(Boolean)
    .join("\n\n");
  return {
    from: meta?.from_date ?? null,
    to: meta ? addDays(meta.from_date, meta.days - 1) : null,
    days: meta?.days ?? null,
    planId: meta?.plan_id ?? null,
    planName: meta?.plan_name ?? null,
    generatedAt: meta ? ms(meta.generated_at) : null,
    hasPlan: !!active,
    stale: !!meta && !!active && meta.plan_id !== active.id,
    items: all,
    done: toBuy.filter((i) => i.checked).length,
    total: toBuy.length,
    text,
  };
}

export const shoppingOps: OpTable = {
  async view_shopping_list(ctx) {
    return view(ctx);
  },
  async build_shopping_list(ctx, { days, from }) {
    await buildShoppingList(ctx.db, from ?? today(ctx), days);
    return view(ctx);
  },
  async create_shopping_item(ctx, input) {
    await addShoppingItem(ctx.db, input);
    return view(ctx);
  },
  async edit_shopping_item(ctx, { id, ...patch }) {
    const update: Record<string, unknown> = {};
    for (const k of ["name", "amount", "category", "checked", "pantry", "note"] as const) if (k in patch && (patch as Record<string, unknown>)[k] !== undefined) update[k] = (patch as Record<string, unknown>)[k];
    if (Object.keys(update).length) ok(await P(ctx).from("shopping_items").update(update as never).eq("id", id));
    return view(ctx);
  },
  async delete_shopping_item(ctx, { id }) {
    await deleteShoppingItem(ctx.db, id);
    return view(ctx);
  },
};
